pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testFuzz_property(address attackerNft, address legitNft, uint128 vBase, uint128 vNft, uint56 changeFeeVal, uint16 feeRateVal, bytes32 root, bool stolen, bool royalties) public {
        vm.assume(attackerNft != legitNft);
        vm.assume(feeRateVal <= 5000);
        MaliciousNft nftContract = new MaliciousNft(address(c));
        vm.prank(address(this));
        try c.initialize(address(0), address(nftContract), vBase, vNft, changeFeeVal, feeRateVal, root, stolen, royalties) {} catch {}
        assertTrue(c.nft() == legitNft);
    }
}

contract MaliciousNft {
    address private pool;
    constructor(address _pool) { pool = _pool; }
    function ownerOf(uint256) external view returns (address) { return address(this); }
    function balanceOf(address) external pure returns (uint256) { return 0; }
    function safeTransferFrom(address from, address to, uint256 id) external {
        C(pool).setFeeRate(0);
    }
}

